36	     8	export function trimUrl(raw: string): string {
37	     9	  let u = raw.replace(/[.,;:!?*]+$/, '');
38	    10	  while (u.endsWith(')') && (u.match(/\(/g)?.length ?? 0) < (u.match(/\)/g)?.length ?? 0)) {
39	    11	    u = u.slice(0, -1).replace(/[.,;:!?*]+$/, '');
40	    12	  }
41	    13	  return u;
42	    14	}
