45	    17	export function extractUrls(text: string): string[] {
46	    18	  const out: string[] = [];
47	    19	  for (const m of text.matchAll(URL_RE)) {
48	    20	    const u = trimUrl(m[0]);
49	    21	    if (!isHttpUrl(u) || out.includes(u)) continue;
50	    22	    out.push(u);
51	    23	  }
52	    24	  return out;
53	    25	}
