    10	/** GET /api/preview?url= — og: metadata for a page URL, cached in wf_link_previews. Image URLs are never fetched. */
    11	export async function GET(req: Request) {
    12	  const url = new URL(req.url).searchParams.get('url') ?? '';
    13	  if (url.length > 2048 || !isHttpUrl(url)) return bad('http 또는 https 주소만 미리 볼 수 있어요.');
    14	  if (isImageUrl(url)) return ok({ url, kind: 'image', title: null, description: null, image: url, site: hostOf(url) });
    15	
    16	  const d = wf();
    17	  const hit = d.prepare('SELECT * FROM wf_link_previews WHERE url = ?').get(url);
    18	  if (hit) {
    19	    return ok({
    20	      url, kind: hit.kind === 'image' ? 'image' : 'page', title: (hit.title as string | null) ?? null,
    21	      description: (hit.description as string | null) ?? null, image: (hit.image as string | null) ?? null, site: (hit.site as string | null) ?? null,
    22	    });
    23	  }
    24	  try {
    25	    const p = await fetchPreview(url);
    26	    d.prepare(
    27	      `INSERT INTO wf_link_previews (url, kind, title, description, image, site, fetched_at) VALUES (?, ?, ?, ?, ?, ?, ?)
    28	       ON CONFLICT(url) DO UPDATE SET kind = excluded.kind, title = excluded.title, description = excluded.description,
    29	       image = excluded.image, site = excluded.site, fetched_at = excluded.fetched_at`,
    30	    ).run(url, p.kind, p.title, p.description, p.image, p.site, new Date().toISOString());
    31	    return ok(p);
    32	  } catch (e) {
    33	    // shortcut: failures are not cached, so a dead link is re-fetched on every view; cache with a TTL if that gets slow
    34	    return Response.json(
    35	      { url, kind: 'page', title: null, description: null, image: null, site: hostOf(url), error: (e as Error).message.slice(0, 200) },
    36	      { status: 200 },
    37	    );
    38	  }
    39	}
