    17	  const d = wf();
    18	
    19	  if (action === 'freeze') {
    20	    if (card.status !== 'active') return bad('진행중인 카드만 동결할 수 있어요.', 409);
    21	    const r = await decisionFor(card, cardMessages(id));
    22	    // the status check in WHERE keeps a concurrent undo from being overwritten while the model was thinking
    23	    const u = d.prepare("UPDATE wf_cards SET status = 'frozen', decision = ? WHERE id = ? AND status = 'active'").run(r.decision, id);
    24	    if (!u.changes) return bad('카드 상태가 바뀌었어요. 새로고침해 주세요.', 409);
    25	    return Response.json({ card: { ...card, status: 'frozen', decision: r.decision }, provider: r.provider, error: r.error });
    26	  }
    27	  if (action === 'undo') {
    28	    const next = card.status === 'active' ? 'cancelled' : 'active';
    29	    d.prepare('UPDATE wf_cards SET status = ?, decision = NULL WHERE id = ?').run(next, id);
    30	    return Response.json({ card: { ...card, status: next, decision: null } });
    31	  }
