    23	/** fetch + JSON with the server's Korean error message surfaced as the Error message. */
    24	export async function api<T>(url: string, method: string, body?: unknown): Promise<T> {
    25	  const res = await fetch(url, {
    26	    method,
    27	    headers: body === undefined ? undefined : { 'content-type': 'application/json' },
    28	    body: body === undefined ? undefined : JSON.stringify(body),
    29	  });
    30	  if (res.status === 204) return undefined as T;
    31	  const data = (await res.json().catch(() => ({}))) as { error?: string };
    32	  if (!res.ok) throw new Error(data.error ?? `요청이 실패했어요 (${res.status}).`);
    33	  return data as T;
    34	}

