content.content:
.wf-empty-page { padding: var(--space-xl) var(--gutter); }

/* ---------- canvas (React Flow themed through its own variables) ---------- */
.wf-canvas { position: relative; flex: 1; min-height: 0; background: var(--color-paper-2); }
.react-flow {
  --xy-background-color: var(--color-paper-2);
  --xy-background-pattern-color: var(--color-canvas-dot);
  --xy-edge-stroke: var(--color-edge);
  --xy-edge-stroke-selected: var(--color-accent);
  --xy-edge-stroke-width: 1.5;
  --xy-connectionline-stroke: var(--color-accent);
  --xy-connectionline-stroke-width: 1.5;
  --xy-handle-background-color: var(--color-surface);
  --xy-handle-border-color: var(--color-rule-2);
  --xy-minimap-background-color: var(--color-surface);
  --xy-minimap-mask-background-color: color-mix(in oklab, var(--color-paper-3) 70%, transparent);
  --xy-minimap-mask-stroke-color: var(--color-rule-2);
  --xy-minimap-node-background-color: var(--color-rule-2);
  --xy-controls-button-background-color: var(--color-surface);
  --xy-controls-button-background-color-hover: var(--color-paper-3);
  --xy-controls-button-color: var(--color-ink-2);
  --xy-controls-button-color-hover: var(--color-ink);
  --xy-controls-button-border-color: var(--color-rule);
  --xy-controls-box-shadow: var(--shadow-card);
  --xy-attribution-background-color: transparent;
  --xy-selection-background-color: color-mix(in oklab, var(--color-accent) 8%, transparent);
  --xy-selection-border: var(--rule-hair) dashed var(--color-accent);
  color: var(--color-ink);
  font-family: var(--font-body);
}
.react-flow__controls { overflow: hidden; border: var(--rule-hair) solid var(--color-rule); border-radius: var(--radius-input); }
.react-flow__controls-button { width: var(--control-h-sm); height: var(--control-h-sm); }
.react-flow__controls-button:focus-visible { outline: 2px solid var(--color-focus); outline-offset: -2px; }
.react-flow__minimap { overflow: hidden; border: var(--rule-hair) solid var(--color-rule); border-radius: var(--radius-input); }
.react-flow__minimap-node.mm--active { fill: var(--color-accent); }
.react-flow__minimap-node.mm--frozen { fill: var(--color-frozen); }
.react-flow__minimap-node.mm--cancelled { fill: var(--color-rule-2); }
.react-flow__attribution { color: var(--color-muted); font-size: var(--text-xs); }
.react-flow__attribution a { color: inherit; }

/* connectors: into an active card = accent, into a cancelled card = dashed */
.react-flow__edge.edge--active .react-flow__edge-path { stroke: var(--color-edge-active); }
.react-flow__edge.edge--cancelled .react-flow__edge-path { stroke-dasharray: 6 5; }
.react-flow__edge.selected .react-flow__edge-path, .react-flow__edge:focus-visible .react-flow__edge-path { stroke: var(--color-accent); stroke-width: 3; }
.react-flow__edge:focus-visible { outline: none; }

/* ports: 10px squares at the vertical centre of each side, a wider invisible hit area */
.react-flow__handle { width: 10px; height: 10px; border-radius: var(--radius-mark); border: var(--rule-hair) solid var(--color-rule-2); background: var(--color-surface); }
.react-flow__handle::after { content: ""; position: absolute; inset: calc(var(--space-xs) * -1); }
@media (hover: hover) { .react-flow__handle:hover { background: var(--color-accent); border-color: var(--color-accent-edge); } }
.react-flow__handle.connectingto, .react-flow__handle.valid { background: var(--color-accent); border-color: var(--color-accent-edge); }
.node__chat { max-height: 360px; overflow-y: auto; overscroll-behavior: contain; padding-right: var(--space-2xs); cursor: text; }
.node__skel { width: 80%; }
.node__skel + .node__skel { width: 55%; }

.msg__time { margin-left: var(--space-2xs); color: var(--color-muted); font-size: var(--text-xs); font-weight: 400; }
.msg--user .msg__time { margin-left: 0; }
.msg__body ul, .msg__body ol { padding-left: var(--space-md); }
.msg__body li + li { margin-top: var(--space-3xs); }
.msg__body strong { font-weight: 600; }

/* ---------- gallery additions ---------- */
/* fixed slide width so the next tile peeks; minmax(0, 78%) in tokens.css lets two tiles shrink to 50% each */
.gallery__track[data-view="slide"] { grid-auto-columns: 78%; }
.gallery__nav { display: flex; align-items: center; justify-content: flex-end; gap: var(--space-xs); }
.preview__btn { width: 100%; padding: 0; border: 0; background: none; font: inherit; text-align: left; cursor: zoom-in; }
.preview__btn:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }
.preview__title--url { font-family: var(--font-mono); font-size: var(--text-xs); font-weight: 400; word-break: break-all; }
.preview__skel { width: 100%; height: 100%; border-radius: 0; }

/* ---------- lightbox ---------- */
.lightbox {
  width: min(1100px, calc(100% - 2 * var(--gutter))); max-height: calc(100dvh - 2 * var(--gutter)); padding: var(--space-sm);
  border: var(--rule-hair) solid var(--color-rule); border-radius: var(--radius-card); background: var(--color-surface); color: var(--color-ink);
}
.lightbox::backdrop { background: color-mix(in oklab, var(--color-graphite) 72%, transparent); }
.lightbox img { width: auto; max-height: calc(100dvh - 2 * var(--gutter) - 5rem); margin-inline: auto; object-fit: contain; border-radius: var(--radius-inner); }
.lightbox__bar { display: flex; align-items: center; justify-content: space-between; gap: var(--space-sm); margin-top: var(--space-sm); min-width: 0; }
.lightbox__bar .url { overflow: hidden; font-family: var(--font-mono); text-overflow: ellipsis; white-space: nowrap; }

/* ---------- add-card popover and empty canvas ---------- */
.wf-add { position: absolute; top: var(--space-md); right: var(--space-md); z-index: var(--z-dropdown); width: min(22rem, calc(100% - 2 * var(--space-md))); box-shadow: var(--shadow-raised); }
.wf-add__body { display: grid; gap: var(--space-sm); }
.wf-overlay { position: absolute; inset: 0; display: grid; place-items: center; pointer-events: none; }
.wf-overlay > * { pointer-events: auto; background: var(--color-paper); }

@media (max-width: 40rem) {
  .wf-toolbar__actions { margin-left: 0; }
  .wf-toolbar__hint { text-align: left; }
  .react-flow__minimap { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .node__body { animation: none; }
  .node { transition: none; }
}
